class FrequencyEncoderDF(sklearn.base.BaseEstimator, sklearn.base.TransformerMixin):

    def __init__(self, cols=None):
        self.cols = cols
        self.freq_maps_ = {}

    def fit(self, X, y=None):
        self.cols_ = self.cols or X.select_dtypes(include='object').columns.tolist()
        for str in self.cols_:
