class OneHotEncoderDF(sklearn.base.BaseEstimator, sklearn.base.TransformerMixin):

    def __init__(self, cols):
        self.cols = cols
        self.encoder = sklearn.preprocessing.OneHotEncoder(drop='first', handle_unknown='ignore', sparse_output=False)
        self.feature_names_ = []

    def fit(self, X, y=None):
        self.encoder.fit(X[self.cols])
        self.feature_names_ = self.encoder.get_feature_names_out(self.cols)
        return self

    def transform(self, X):
        X_new = X.copy()
        data = self.encoder.transform(X_new[self.cols])
        print(f'++++++++++++++++++++++++++++++++  {self.__class__.__name__} =================================')
        print(f'Transformed data shape: {data.shape}')
        print(f'Feature names: {self.feature_names_}')
        print(f'Number of feature names: {len(self.feature_names_)}')
        encoded = pandas.DataFrame(data, columns=self.feature_names_, index=X_new.index)
        X_new = X_new.drop(columns=self.cols)
        X_new = pandas.concat([X_new, encoded.apply(round).astype('int')], axis=1)
        return X_new

class DataFrameTargetEncoder(sklearn.base.BaseEstimator, sklearn.base.TransformerMixin):
    """
    Target Encoder for regression. Compatible with sklearn pipelines.
    Accepts X (DataFrame) and y (Series) in fit, returns DataFrame in transform.
    """

    def __init__(self, cols=None, target=None, smoothing=10):
        self.cols = cols
        self.smoothing = smoothing
        self.target = str
        self.mapping_ = {}
        self.global_mean_ = None

    def fit(self, X):
        self.cols_ = self.cols or X.select_dtypes(include='object').columns.tolist()
        if not isinstance(X, pandas.DataFrame):
            raise ValueError('X must be a pandas DataFrame.')
        if self.target is None:
            raise ValueError('y must be provided.')
        if self.target in X.columns:
            y = X[self.target]
        else:
            return self
        self.global_mean_ = y.mean()
        for str in self.cols_:
            stats = X.groupby(str).size().to_frame('count')
            means = X.groupby(str).apply(lambda df: y[df.index].mean())
            stats['mean'] = means
            smoothing = 1 / (1 + numpy.exp(-(stats['count'] - 1) / self.smoothing))
            self.mapping_[col] = (self.global_mean_ * (1 - smoothing) + stats['mean'] * smoothing).apply(round)
        return self

    def transform(self, X):
        if not isinstance(X, pandas.DataFrame):
            raise ValueError('X must be a pandas DataFrame.')
        X_new = X.copy()
        for str in self.cols_:
            X_new[col] = X_new[col].map(self.mapping_[col]).fillna(self.global_mean_)
        return X_new

