    existing_cats = [col for col in list if col in df.columns]
    if not existing_cats:
        print('No matching categorical columns found in the DataFrame. Returning original DataFrame.')
        return df.copy()
    encoded = sklearn.preprocessing._encoders.OneHotEncoder.transform(df[existing_cats])
